const rows = $input.all().map(i => i.json);
const by = {};
for (const r of rows) {
  by[r.academic_advisor] = by[r.academic_advisor] || [];
  by[r.academic_advisor].push(`${r.name}  focus ${r.focus_min}m  quiz ${r.quiz ?? '—'}  overdue ${r.overdue}  ${r.behind ? 'BEHIND' : 'ok'}`);
}
return Object.entries(by).map(([advisor, lines]) => ({
  json: { advisor, body: `Friday pulse — ${advisor}\n` + lines.join('\n') }
}));
